 public static object Main(){var scene=EditorSceneManager.NewPreviewScene();var root=new GameObject("Dummy render audit");SceneManager.MoveGameObjectToScene(root,scene);RenderTexture rt=null;var errors=new List<string>();Application.LogCallback capture=(message,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(message);};Application.logMessageReceived+=capture;
 try {var go=new GameObject("Sprite template");go.transform.SetParent(root.transform,false);var d=go.AddComponent<GfxSpriteDriver>();d.Configure(new GfxSpriteParams{SystemId="101",Width=2,Height=2,DestBlend=2,ElementIndex=0},Texture2D.whiteTexture,false,new List<string>());d.OnGfxTick(0,1);
