 var batchControl=batches[0];var originalMat=batchControl.Material;var directControl=Immediate(cam,rt,batchControl,1,false);var immediate=new JArray();foreach(var alpha in new[]{1f,.5f,0f})immediate.Add(new JObject{["alpha"]=alpha,["red"]=Immediate(cam,rt,batchControl,alpha)});var supported=new Material(Shader.Find("Universal Render Pipeline/Unlit"));supported.SetColor("_BaseColor",Color.white);supported.SetFloat("_Cull",0);supported.enableInstancing=true;batchControl.Material=supported;batchControl.SetSlot(0,Vector3.zero,Quaternion.identity,Vector3.one,0,1);batchControl.Render();var instancedControl=Pixel(cam,rt);var immediateControl=Immediate(cam,rt,batchControl,1);batchControl.Material=originalMat;UnityEngine.Object.DestroyImmediate(supported);
 var result=new JObject{["controlRed"]=control,["instancedControlRed"]=instancedControl,["immediateControlRed"]=immediateControl,["directGfxControlRed"]=directControl,["immediateSamples"]=immediate,["accepted"]=accepted,["batchCount"]=batches.Count,["samples"]=values,["errors"]=JArray.FromObject(errors)};File.WriteAllText("B:/Git/Godot_Forsaken_World_Editor/.validation/gfx-parity/unity-dummy-render.json",result.ToString());return result;
